SELECT item_name
FROM items
WHERE item_id = #{itemId}
AND company_id = #{companyId}
LIMIT 1

SELECT item_name
FROM pointsmall_items
WHERE item_id = #{itemId}
AND company_id = #{companyId}
LIMIT 1

SELECT *
FROM items
WHERE item_id = #{itemId}
AND company_id = #{companyId}
LIMIT 1

SELECT *
