SELECT AVG(COALESCE(tr.star, 5)) AS avg_star
FROM orders_normal_orders o
LEFT JOIN trade_rate tr
	ON o.order_id = tr.order_id AND o.company_id = tr.company_id
WHERE o.company_id = #{companyId}
AND o.distributor_id = #{distributorId}
